const CMOR_ST={g:"all",q:""};

function cmtabMor(){
const f=CHMOR.filter(r=>{
const mg=CMOR_ST.g=="all"||(CMOR_ST.g=="pre"&&(r[0].includes("vivo")||r[0].includes("Insensibilização")||r[0].includes("Marmoreio")))||(CMOR_ST.g=="rig"&&(r[0].includes("Rigor")||r[0].includes("Contração")||r[0].includes("consumida")||r[0].includes("Sódio")))||(CMOR_ST.g=="mat"&&(r[0].includes("Maturação")||r[0].includes("Cozimento")||r[0].includes("macio")))||(CMOR_ST.g=="cor"&&(r[0].includes("vácuo")||r[0].includes("marrom")||r[0].includes("Freezer")))||(CMOR_ST.g=="anom"&&(r[0].includes("PSE")||r[0].includes("DFD")||r[0].includes("Pescado")||r[0].includes("cultivada")));
const mq=!CMOR_ST.q||r.some(c=>c.toLowerCase().includes(CMOR_ST.q.toLowerCase()));
return mg&&mq;
});
if(!f.length)return`<p style="color:var(--mu);margin:12px 0">Nenhum conceito encontrado.</p>`;
return`<div class=w><table class=ct><thead><tr><th>Alimento / Situação</th><th>O que acontece no alimento</th><th>Por quê (Mecanismo Bioquímico)</th><th>Dica e Alerta do Professor</th></tr></thead><tbody>${f.map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td><td><small>${r[3]}</small></td></tr>`).join("")}</tbody></table></div>`;
}

function cheatMor(){
return`<section id="t12"><h2>Tabela: Alterações em Alimentos de Origem Animal</h2><p>Guia definitivo integrando os 12 tópicos com as tabelas de resumo da Profa. Flávia Custódio (ALM018). Filtre por categoria ou pesquise qualquer termo técnico.</p><div style="display:flex;gap:6px;flex-wrap:wrap;margin:10px 0"><button class="ch ${CMOR_ST.g=='all'?'on':''}" data-mg2="all">Todos (18)</button><button class="ch ${CMOR_ST.g=='pre'?'on':''}" data-mg2="pre">Pré-Abate e Estrutura</button><button class="ch ${CMOR_ST.g=='rig'?'on':''}" data-mg2="rig">Glicólise e Rigor</button><button class="ch ${CMOR_ST.g=='mat'?'on':''}" data-mg2="mat">Maturação e Cocção</button><button class="ch ${CMOR_ST.g=='cor'?'on':''}" data-mg2="cor">Cor e Mioglobina</button><button class="ch ${CMOR_ST.g=='anom'?'on':''}" data-mg2="anom">Anomalias e Pescados</button></div><input id=cqm2 value="${CMOR_ST.q.replace(/"/g,"&quot;")}" placeholder="Buscar conceito (ex: calpaína, rigor, pse, dfd, marmoreio, mioglobina)..." aria-label="Buscar conceito post mortem" style="width:100%;padding:10px 12px;border:1px solid var(--bd);border-radius:8px;background:var(--cd);color:var(--tx);font:inherit"><div id=cmw2>${cmtabMor()}</div>`+(typeof simBancadaHtml==="function"?simBancadaHtml("mor"):"")+`<h3>Cinética e Parâmetros Fisiológicos por Espécie</h3>`+tb(["Espécie animal","Instalação do Rigor","Rigor Pleno na Carcaça","pH final pós-24h","Principais anomalias e riscos"],[["Bovinos","10 a 12 horas","15 a 24 horas a 7 °C","5,5 a 5,8","Carne DFD (estresse crônico) e cold shortening"],["Suínos","1 a 2 horas","4 a 12 horas (média 6-8h)","5,5 a 5,8","Carne PSE (estresse agudo / gene Halotano)"],["Aves (frango/peru)","15 a 30 minutos","1 a 3 horas no fluxo contínuo","5,6 a 5,9","PSE em perus e hematomas de pendura"],["Pescados marinhos","Imediato na captura","Rápido e efêmero","6,2 a 6,6","Autólise acelerada por proteases; exige congelamento imediato"]])+`<h3>Regras de Ouro de Concurso e Prova da Profa. Flávia</h3>`+tb(["Afirmação Clássica de Prova","Veredito Bromatológico","Explicação Científica Definitiva"],[["'As calpaínas digerem a actina e a miosina durante a maturação'","FALSA","Calpaínas clivam apenas as âncoras da linha Z, titina e desmina, soltando os sarcômeros."],["'O relaxamento muscular celular é um recuo passivo elástico'","FALSA","Relaxar é estritamente ativo: bombas SERCA consomem ATP continuamente para bombear Ca²⁺."],["'O líquido vermelho acumulado na bandeja de bife é sangue'","FALSA","O animal sofre sangria total; o líquido é água celular com mioglobina e eletrólitos."],["'A carne DFD é segura para consumo porque retém muita água'","FALSA","Com pH > 6,0 a barreira ácida é anulada; a carne DFD apodrece rapidamente por bactérias."],["'Carne embalada a vácuo com cor púrpura escura está estragada'","FALSA","Trata-se de desoximioglobina na ausência de oxigênio; aguarde 15 min de contato com o ar que ela floresce em vermelho-vivo (bloom)."],["'Picanha é o corte anatomicamente mais macio do boi'","FALSA","O corte mais macio é o filé mignon (Psoas major); a picanha é carne intermediária que exige corte correto."]])+`</section>`;
}

document.addEventListener("click",e=>{const b=e.target.closest("[data-mg2]");if(!b)return;CMOR_ST.g=b.dataset.mg2;$("#cmw2").innerHTML=cmtabMor()});
document.addEventListener("input",e=>{if(e.target.id=="cqm2"){CMOR_ST.q=e.target.value;$("#cmw2").innerHTML=cmtabMor()}});

